function units(q){const matches=q.match(/"[^"]*(?:"|$)|“[^”]*(?:”|$)|[^\s"“]+/g)||[];const segmenter=typeof Intl.Segmenter==='function'?new Intl.Segmenter('zh',{granularity:'word'}):null;return matches.flatMap(m=>{if(/^["“]/.test(m))return [fold(m.replace(/^["“]|["”]$/g,''))].filter(Boolean);if(!q.match(/\s/)&&segmenter&&/[\u3400-\u9fff]/.test(m))return [...segmenter.segment(fold(m))].filter(p=>p.isWordLike).map(p=>p.segment);return [fold(m)]}).filter(Boolean)}
