function runSearch(){if(!search?.open)return;clearTimeout(search.debounce);search.pending=false;const u=units(search.q),invalid=search.tags.some(id=>!tag(id));search.results=invalid?[]:project().nodes.filter(n=>n.type==='card'&&search.tags.every(id=>(n.tags||[]).includes(id))&&u.every(q=>fold(n.title).includes(q)||fold(plain(n)).includes(q))).sort((a,b)=>{const rank=n=>u.length&&u.every(q=>fold(n.title).includes(q))?0:u.some(q=>fold(n.title).includes(q))?1:2;return rank(a)-rank(b)||(b.updatedAt||0)-(a.updatedAt||0)||a.id.localeCompare(b.id)});if(!search.results.some(n=>n.id===search.preview)){search.preview=search.results[0]?.id||null;search.hit=0}$('#fp-filter-count').textContent=search.tags.length?`(${search.tags.length})`:'';$('#fp-selected-tags').innerHTML=search.tags.map(id=>`<button class="fp-tag" data-remove-filter="${id}">${esc(tag(id)?.name||'已删除标签')} ×</button>`).join('');$$('[data-remove-filter]').forEach(el=>el.onclick=()=>{search.tags=search.tags.filter(id=>id!==el.dataset.removeFilter);runSearch()});$('#fp-match-info').hidden=!u.length;$('#fp-result-count').textContent=invalid?'存在已删除标签，请先移除':`${search.results.length} 张卡片`;$('#fp-result-list').innerHTML=search.results.length?search.results.map(n=>{const b=plain(n),positions=u.map(q=>fold(b).indexOf(q)).filter(i=>i>=0),start=positions.length?Math.max(0,Math.min(...positions)-25):0;return `<button class="fp-result ${n.id===search.preview?'active':''}" data-result="${n.id}" role="option" aria-selected="${n.id===search.preview}"><div class="fp-result-title">${highlight(n.title||'未命名卡片',u)}</div><p>${start?'…':''}${highlight(b.slice(start,start+130),u)}${b.length>start+130?'…':''}</p><div>${(n.tags||[]).map(tagHTML).join('')}</div></button>`}).join(''):`<div class="fp-empty"><span>${icon('search','⌕')}</span><h3>${invalid?'标签已失效':'没有找到卡片'}</h3><p>${invalid?'移除已删除标签后重新搜索':'试试修改关键词，或清空部分标签条件'}</p></div>`;$$('[data-result]').forEach(el=>{el.onclick=()=>{search.preview=el.dataset.result;search.hit=0;drawPreview();$$('[data-result]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-selected',b===el)});$('.fp-search').classList.add('show-preview')};el.onkeydown=e=>{if(e.isComposing)return;let i=search.results.findIndex(n=>n.id===el.dataset.result);if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();i=Math.max(0,Math.min(search.results.length-1,i+(e.key==='ArrowDown'?1:-1)));search.preview=search.results[i].id;search.hit=0;drawPreview();$$('[data-result]').forEach(b=>b.classList.toggle('active',b.dataset.result===search.preview));$(`[data-result="${search.preview}"]`).focus()}else if(e.key==='Enter'){e.preventDefault();search.preview=el.dataset.result;openResult()}}});drawPreview();persistSearch()}
function ranges(text,u){const f=fold(text),out=[];for(const term of u){let i=0;while(term&&(i=f.indexOf(term,i))!==-1){out.push([i,i+term.length]);i+=Math.max(1,term.length)}}out.sort((a,b)=>a[0]-b[0]);const merged=[];for(const r of out){if(merged.length&&r[0]<merged.at(-1)[1])merged.at(-1)[1]=Math.max(merged.at(-1)[1],r[1]);else merged.push(r)}return merged}
