function render(){if(editorId&&editorProject!==project().id){closeEditor();if(search?.open)closeSearch();search=null;return}if(editorId){const body=$('#fp-body'),n=card(editorId);if((!n&&body)||(n&&!body))renderEditor();else if(n&&body&&!before&&!body.contains(document.activeElement)&&document.activeElement!==$('#fp-title')){if(body.innerHTML!==(n.bodyHtml||'')){body.innerHTML=n.bodyHtml?sanitize(n.bodyHtml):(n.body||'').split('\n').map(p=>`<p>${esc(p)||'<br>'}</p>`).join('')}$('#fp-title').value=n.title||'';$('#fp-card-tags').innerHTML=(n.tags||[]).map(tagHTML).join('')}followSelection()}}
